<div class="grid"><form id="tool" class="panel"><label>Customer price</label><input name="revenue" type="number" min="0" step="0.01" required><label>Materials</label><input name="materials" type="number" min="0" step="0.01" required><label>Labor</label><input name="labor" type="number" min="0" step="0.01" required><label>Other costs</label><input name="other" type="number" min="0" step="0.01" value="0" required><button>Check this job</button><p id="error" class="error"></p></form><section id="result" class="stat hidden"><span>Estimated profit</span><b id="profit"></b><p><strong id="margin"></strong> margin</p><p id="breakdown"></p><p id="usage"></p></section></div>
<div id="upgrade-slot"></div>
<script>
const TOOL_KEY='profit-peek';
const PERIOD=<?= json_encode($usage['period'] ?? '') ?>;
if(<?= $low ? 'true' : 'false' ?>){const seen='bb_m80_'+PERIOD;if(!localStorage.getItem(seen)){localStorage.setItem(seen,'1');bbTrack('usage_milestone_80',{tool:TOOL_KEY,used:<?= (int) ($usage['used'] ?? 0) ?>,limit:<?= (int) ($usage['limit'] ?? 0) ?>})}}
function upgradeCard(){return `<div class="upgrade-card"><h2>Out of free actions.</h2><p class="lede">You used all <?= (int) ($usage['limit'] ?? 75) ?> free actions this month. Helper gives you 1,500 actions for $12/month. Operator gives you 6,000 actions plus a custom tool built for you in 36 hours for $49/month.</p><p><a class="button" data-plan="helper" href="/checkout/?plan=helper">Get Helper, $12/mo</a> <a class="button secondary" data-plan="operator" href="/checkout/?plan=operator">Get Operator, $49/mo</a></p><p><a href="/account/">See your usage</a></p></div>`}
const form=document.querySelector('#tool');let attempt=crypto.randomUUID();form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;document.querySelector('#error').textContent='';document.querySelector('#upgrade-slot').innerHTML='';const session=await fetch('/api/session.php').then(r=>r.json());const fields=Object.fromEntries(new FormData(form));const response=await fetch('/api/tools/profit-peek.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,csrf:session.csrf,idempotencyKey:attempt})});const data=await response.json();button.disabled=false;if(!response.ok){if(response.status===402){bbTrack('limit_reached',{tool:TOOL_KEY});bbTrack('upgrade_prompt_shown',{tool:TOOL_KEY,context:'limit'});document.querySelector('#upgrade-slot').innerHTML=upgradeCard();document.querySelectorAll('#upgrade-slot [data-plan]').forEach(a=>a.addEventListener('click',()=>bbTrack('upgrade_clicked',{plan:a.dataset.plan,context:'limit',tool:TOOL_KEY})))}else{document.querySelector('#error').textContent=data.error}return}attempt=crypto.randomUUID();bbTrack('action_completed',{tool:TOOL_KEY,used:data.usage.used,limit:data.usage.limit,remaining:data.usage.remaining});const money=new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'});document.querySelector('#profit').textContent=money.format(data.result.profit);document.querySelector('#margin').textContent=data.result.margin+'%';document.querySelector('#breakdown').textContent=money.format(data.result.revenue)+' revenue minus '+money.format(data.result.cost)+' costs.';document.querySelector('#usage').textContent=data.usage.remaining+' actions remaining this month.';document.querySelector('#result').classList.remove('hidden')});
</script><?php endif; ?></main></body></html>
